import java.util.*;
import java.io.*;

public class Main {
    static final long INF = 100000000000000000L;
    static final int MAXNODES = 1001;
    static final int[] dir_x = {0, 0, -1, 1};
    static final int[] dir_y = {-1, 1, 0, 0};
    static List<Integer>[] adj = new ArrayList[MAXNODES];
    static boolean[] visited = new boolean[MAXNODES];
    static int[] match = new int[MAXNODES];

    static {
        for (int i = 0; i < MAXNODES; i++) {
            adj[i] = new ArrayList<>();
        }
    }

    static boolean is_valid_cell(int x, int y, String[] grid) {
        int n = grid.length;
        return x >= 0 && y >= 0 && x < n && y < n && grid[x].charAt(y) != 'Y' && grid[x].charAt(y) != 'Z';
    }

    static long[][] compute_bfs(int start_x, int start_y, String[] grid) {
        int n = grid.length;
        long[][] dist = new long[n][n];
        for (long[] row : dist) Arrays.fill(row, INF);
        dist[start_x][start_y] = 0;
        Deque<int[]> q = new ArrayDeque<>();
        q.offer(new int[]{start_x, start_y});
        while (!q.isEmpty()) {
            int[] cell = q.pollFirst();
            int x = cell[0], y = cell[1];
            for (int d = 0; d < 4; d++) {
                int nx = x + dir_x[d], ny = y + dir_y[d];
                if (!is_valid_cell(nx, ny, grid) || dist[nx][ny] != INF) continue;
                dist[nx][ny] = dist[x][y] + 1;
                q.offer(new int[]{nx, ny});
            }
        }
        return dist;
    }

    static void build_graph(Scanner sc) {
        int n = sc.nextInt();
        int t = sc.nextInt();
        String[] s1 = new String[n];
        String[] s2 = new String[n];
        for (int i = 0; i < n; i++) s1[i] = sc.next();
        for (int i = 0; i < n; i++) s2[i] = sc.next();

        int rx = -1, ry = -1;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (s1[i].charAt(j) == 'Z') {
                    rx = i;
                    ry = j;
                }
            }
        }

        long[][] reac_dist = compute_bfs(rx, ry, s1);

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (!is_valid_cell(i, j, s1)) continue;
                long[][] from_cell = compute_bfs(i, j, s1);
                for (int x = 0; x < n; x++) {
                    for (int y = 0; y < n; y++) {
                        if (!is_valid_cell(x, y, s1) || from_cell[x][y] > t || from_cell[x][y] > reac_dist[x][y]) continue;
                        if (from_cell[x][y] == reac_dist[x][y]) {
                            boolean can_move = false;
                            for (int dir_idx = 0; dir_idx < 4; dir_idx++) {
                                int xto = x + dir_x[dir_idx];
                                int yto = y + dir_y[dir_idx];
                                if (!is_valid_cell(xto, yto, s1) || from_cell[xto][yto] >= reac_dist[xto][yto]) continue;
                                can_move = true;
                            }
                            if (!can_move) continue;
                        }
                        int max1 = s1[i].charAt(j) - '0';
                        int max2 = s2[x].charAt(y) - '0';
                        for (int num1 = 1; num1 <= max1; num1++) {
                            for (int num2 = 1; num2 <= max2; num2++) {
                                int v1 = 10 * (j + i * 10) + num1;
                                int v2 = 10 * (y + 10 * x) + num2;
                                adj[v1].add(v2);
                            }
                        }
                    }
                }
            }
        }
    }

    static boolean try_match_vertex(int v) {
        if (visited[v]) return false;
        visited[v] = true;
        for (int to : adj[v]) {
            if (match[to] == 0 || try_match_vertex(match[to])) {
                match[to] = v;
                return true;
            }
        }
        return false;
    }

    static void solve_task(Scanner sc) {
        build_graph(sc);
        int total_nodes = MAXNODES - 1; // as per original code, max_n is not explicitly defined, assuming MAXNODES
        for (int i = 0; i < total_nodes; i++) {
            Arrays.fill(visited, false);
            try_match_vertex(i);
        }
        int total_pairs = 0;
        for (int i = 0; i < total_nodes; i++) {
            if (match[i] != 0) total_pairs++;
        }
        System.out.println(total_pairs);
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        solve_task(sc);
        sc.close();
    }
}
